<div class="page-title clearfix"><h1>Email Templates</h1><a class="btn btn-primary float-end" href="<?php echo site_url('email_marketing/templates/create'); ?>">Create template</a></div><div class="card"><table class="table"><thead><tr><th>Name</th><th>Subject</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($templates as $t): ?><tr><td><?php echo esc($t->name); ?></td><td><?php echo esc($t->subject); ?></td><td><?php echo esc($t->created_at); ?></td><td><a href="<?php echo site_url('email_marketing/templates/edit/'.$t->id); ?>">Edit</a> | <a href="<?php echo site_url('email_marketing/templates/preview/'.$t->id); ?>">Preview</a> | <a href="<?php echo site_url('email_marketing/templates/duplicate/'.$t->id); ?>">Duplicate</a> | <form method="post" action="<?php echo site_url('email_marketing/templates/delete/'.$t->id); ?>" style="display:inline"><input type="hidden" name="<?php echo csrf_token(); ?>" value="<?php echo csrf_hash(); ?>"><button class="btn btn-link p0" onclick="return confirm('Delete template?')">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div>
